using OpenUtau.Api;
using DiffSingerNorwegian;

namespace OpenUtau.Core.DiffSinger
{
    [Phonemizer("DiffSinger Norwegian Phonemizer", "DIFFS NO", language: "NO")]
    public class DiffSingerNorwegianPhonemizer : DiffSingerG2pPhonemizer
    {
        // Voicebank dictionary, read from the singer folder.
        protected override string GetDictionaryName() => "dsdict-no.yaml";

        public override string GetLangCode() => "no";

        // NOFABET G2P generated by gen_nofabet_cs.py.
        protected override IG2p LoadBaseG2p() => new NofabetG2p();

        // 24 vowels. Must match the NOFABET vowel set in nofabet.yaml.
        protected override string[] GetBaseG2pVowels() => new string[] {
            "aa", "ae", "aeh", "aej", "aew", "ah", "aj", "ax", "ee", "eh", "ih", "ii",
            "oa", "oah", "oe", "oeh", "oej", "oh", "oj", "oo", "uh", "uu", "yh", "yy"
        };

        // 27 consonants. 24 + 27 = 51, the NOFABET phone count without specials.
        protected override string[] GetBaseG2pConsonants() => new string[] {
            "b", "d", "f", "g", "h", "j", "k", "kj", "l", "lx", "m", "n", "ng", "nx",
            "p", "r", "rd", "rl", "rlx", "rn", "rnx", "rs", "rt", "s", "sj", "t", "v"
        };
    }
}